#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#define MAXN 600
#define MAXTAG 10

bool okName(const char* s,int len){ if(len<1||len>9)return false; for(int i=0;i<len;i++) if(s[i]<'A'||s[i]>'Z')return false; return true; }
bool isValid(const char* code){
  char st[64][MAXTAG]; int top=0; int n=(int)strlen(code), i=0; if(n==0||code[0]!='<')return false;
  while(i<n){
    if(strncmp(code+i,"<![CDATA[",9)==0){ if(top==0)return false; const char* p=strstr(code+i+9,"]]>"); if(!p)return false; i=(int)(p-code)+3; continue; }
    if(code[i]=='<'){ const char* p=strchr(code+i+1,'>'); if(!p)return false; int j=(int)(p-code);
      if(code[i+1]=='/'){ int len=j-(i+2); if(!okName(code+i+2,len)||top==0||strncmp(st[top-1],code+i+2,len)!=0)return false; st[--top][0]='\0'; i=j+1; if(top==0&&i!=n)return false; }
      else { int len=j-(i+1); if(!okName(code+i+1,len))return false; memcpy(st[top],code+i+1,len); st[top][len]='\0'; top++; i=j+1; }
    } else { if(top==0)return false; i++; }
  }
  return top==0;
}

