import json, sys

class Solution:
    def isValid(self, code):
        stack=[]
        n=len(code); i=0
        def ok(name):
            return 1 <= len(name) <= 9 and all('A' <= c <= 'Z' for c in name)
        if n == 0 or code[0] != '<':
            return False
        while i < n:
            if code.startswith("<![CDATA[", i):
                if not stack: return False
                j=code.find("]]>", i+9)
                if j == -1: return False
                i=j+3; continue
            if code[i] == '<':
                j=code.find('>', i+1)
                if j == -1: return False
                if code.startswith('</', i):
                    name=code[i+2:j]
                    if not ok(name) or not stack or stack[-1] != name: return False
                    stack.pop(); i=j+1
                    if not stack and i != n: return False
                else:
                    name=code[i+1:j]
                    if not ok(name): return False
                    stack.append(name); i=j+1
            else:
                if not stack: return False
                i += 1
        return not stack

_args=json.loads(sys.stdin.readline())
print(json.dumps(Solution().isValid(_args[0])))

