function isValid(code){
  const stack=[]; let i=0; const n=code.length;
  const ok=s=>s.length>=1&&s.length<=9&&/^[A-Z]+$/.test(s);
  if(n===0||code[0]!=="<") return false;
  while(i<n){
    if(code.startsWith("<![CDATA[",i)){
      if(!stack.length) return false;
      const j=code.indexOf("]]>",i+9); if(j===-1) return false;
      i=j+3; continue;
    }
    if(code[i]==="<"){
      const j=code.indexOf(">",i+1); if(j===-1) return false;
      if(code.startsWith("</",i)){
        const name=code.slice(i+2,j);
        if(!ok(name)||!stack.length||stack[stack.length-1]!==name) return false;
        stack.pop(); i=j+1; if(!stack.length&&i!==n) return false;
      }else{
        const name=code.slice(i+1,j); if(!ok(name)) return false;
        stack.push(name); i=j+1;
      }
    }else{ if(!stack.length) return false; i++; }
  }
  return stack.length===0;
}
